import { themeVersionProjectionToValue } from './theme-version.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('themeVersionProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    theme: { $ref: 'ref-theme' },
    channel: 'value-channel',
    locale: 'value-locale',
    contentHtml: 'value-contentHtml',
    contentText: 'value-contentText',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(themeVersionProjectionToValue(null)).toBeNull();
    expect(themeVersionProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(themeVersionProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      theme: () => ({ uid: 'ref-theme' }),
      channel: 'value-channel',
      locale: 'value-locale',
      contentHtml: 'value-contentHtml',
      contentText: 'value-contentText',
      version: 'value-version',
    } as any;
    expect(themeVersionProjectionToValue(projection)).toEqual(value);
  });
});
